-- ==========================================================
-- SaveMyMeal - Script de création des tables Oracle (DDL)
-- Utilisateur / Schéma : SAVEMEALBDPROD
-- ==========================================================

-- 1. Table Users
BEGIN
   EXECUTE IMMEDIATE '
   CREATE TABLE "Users" (
       "Id" NUMBER(10) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
       "Username" NVARCHAR2(100) NOT NULL,
       "Email" NVARCHAR2(150) NOT NULL,
       "PasswordHash" NVARCHAR2(2000) NOT NULL,
       "Role" NVARCHAR2(50) DEFAULT ''Client'' NOT NULL,
       "CreatedAt" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
       CONSTRAINT "UQ_Users_Email" UNIQUE ("Email"),
       CONSTRAINT "UQ_Users_Username" UNIQUE ("Username")
   )';
EXCEPTION
   WHEN OTHERS THEN
      IF SQLCODE != -955 THEN RAISE; END IF;
END;
/

-- 2. Table Categories
BEGIN
   EXECUTE IMMEDIATE '
   CREATE TABLE "Categories" (
       "Id" NUMBER(10) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
       "Name" NVARCHAR2(100) NOT NULL
   )';
EXCEPTION
   WHEN OTHERS THEN
      IF SQLCODE != -955 THEN RAISE; END IF;
END;
/

-- 3. Table Restaurants
BEGIN
   EXECUTE IMMEDIATE '
   CREATE TABLE "Restaurants" (
       "Id" NUMBER(10) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
       "Name" NVARCHAR2(150) NOT NULL,
       "Address" NVARCHAR2(2000) NOT NULL,
       "PhoneNumber" NVARCHAR2(20) NOT NULL,
       "OwnerId" NUMBER(10) NOT NULL,
       CONSTRAINT "FK_Restaurants_Users" FOREIGN KEY ("OwnerId") 
           REFERENCES "Users"("Id")
   )';
EXCEPTION
   WHEN OTHERS THEN
      IF SQLCODE != -955 THEN RAISE; END IF;
END;
/

-- 4. Table Meals
BEGIN
   EXECUTE IMMEDIATE '
   CREATE TABLE "Meals" (
       "Id" NUMBER(10) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
       "Title" NVARCHAR2(150) NOT NULL,
       "Description" NVARCHAR2(2000) DEFAULT '''' NOT NULL,
       "OriginalPrice" NUMBER(18,2) NOT NULL,
       "DiscountedPrice" NUMBER(18,2) NOT NULL,
       "Quantity" NUMBER(10) NOT NULL,
       "ExpiryDate" TIMESTAMP NOT NULL,
       "RestaurantId" NUMBER(10) NOT NULL,
       "CategoryId" NUMBER(10) NOT NULL,
       CONSTRAINT "FK_Meals_Restaurants" FOREIGN KEY ("RestaurantId") 
           REFERENCES "Restaurants"("Id") ON DELETE CASCADE,
       CONSTRAINT "FK_Meals_Categories" FOREIGN KEY ("CategoryId") 
           REFERENCES "Categories"("Id")
   )';
EXCEPTION
   WHEN OTHERS THEN
      IF SQLCODE != -955 THEN RAISE; END IF;
END;
/

-- 5. Table Orders
BEGIN
   EXECUTE IMMEDIATE '
   CREATE TABLE "Orders" (
       "Id" NUMBER(10) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
       "ClientId" NUMBER(10) NOT NULL,
       "RestaurantId" NUMBER(10) NOT NULL,
       "OrderDate" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
       "Status" NVARCHAR2(50) DEFAULT ''Pending'' NOT NULL,
       "TotalPrice" NUMBER(18,2) NOT NULL,
       CONSTRAINT "FK_Orders_Clients" FOREIGN KEY ("ClientId") 
           REFERENCES "Users"("Id"),
       CONSTRAINT "FK_Orders_Restaurants" FOREIGN KEY ("RestaurantId") 
           REFERENCES "Restaurants"("Id")
   )';
EXCEPTION
   WHEN OTHERS THEN
      IF SQLCODE != -955 THEN RAISE; END IF;
END;
/

-- 6. Table OrderItems
BEGIN
   EXECUTE IMMEDIATE '
   CREATE TABLE "OrderItems" (
       "Id" NUMBER(10) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
       "OrderId" NUMBER(10) NOT NULL,
       "MealId" NUMBER(10) NOT NULL,
       "Quantity" NUMBER(10) NOT NULL,
       "UnitPrice" NUMBER(18,2) NOT NULL,
       CONSTRAINT "FK_OrderItems_Orders" FOREIGN KEY ("OrderId") 
           REFERENCES "Orders"("Id") ON DELETE CASCADE,
       CONSTRAINT "FK_OrderItems_Meals" FOREIGN KEY ("MealId") 
           REFERENCES "Meals"("Id")
   )';
EXCEPTION
   WHEN OTHERS THEN
      IF SQLCODE != -955 THEN RAISE; END IF;
END;
/

-- 7. Table QrCodes
BEGIN
   EXECUTE IMMEDIATE '
   CREATE TABLE "QrCodes" (
       "Id" NUMBER(10) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
       "OrderId" NUMBER(10) NOT NULL,
       "CodeValue" NVARCHAR2(255) NOT NULL,
       "IsUsed" NUMBER(1) DEFAULT 0 NOT NULL,
       "GeneratedAt" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
       CONSTRAINT "UQ_QrCodes_OrderId" UNIQUE ("OrderId"),
       CONSTRAINT "UQ_QrCodes_CodeValue" UNIQUE ("CodeValue"),
       CONSTRAINT "FK_QrCodes_Orders" FOREIGN KEY ("OrderId") 
           REFERENCES "Orders"("Id") ON DELETE CASCADE
   )';
EXCEPTION
   WHEN OTHERS THEN
      IF SQLCODE != -955 THEN RAISE; END IF;
END;
/

-- 8. Table LoyaltyAccounts
BEGIN
   EXECUTE IMMEDIATE '
   CREATE TABLE "LoyaltyAccounts" (
       "Id" NUMBER(10) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
       "UserId" NUMBER(10) NOT NULL,
       "SavePointsBalance" NUMBER(10) DEFAULT 0 NOT NULL,
       CONSTRAINT "UQ_Loyalty_UserId" UNIQUE ("UserId"),
       CONSTRAINT "FK_Loyalty_Users" FOREIGN KEY ("UserId") 
           REFERENCES "Users"("Id") ON DELETE CASCADE
   )';
EXCEPTION
   WHEN OTHERS THEN
      IF SQLCODE != -955 THEN RAISE; END IF;
END;
/

-- Insertion des Catégories par défaut
MERGE INTO "Categories" c
USING (
    SELECT 'Boulangerie & Pâtisserie' AS "Name" FROM dual UNION ALL
    SELECT 'Plats Cuisinés & Traiteur' AS "Name" FROM dual UNION ALL
    SELECT 'Paniers Surprise' AS "Name" FROM dual UNION ALL
    SELECT 'Sushi & Cuisine Asiatique' AS "Name" FROM dual UNION ALL
    SELECT 'Pizzas & Sandwiches' AS "Name" FROM dual
) src
ON (c."Name" = src."Name")
WHEN NOT MATCHED THEN
    INSERT ("Name") VALUES (src."Name");

COMMIT;
